#!/bin/bash
# Generated by dsh-super-injector dev_scaffold_plugin.
# Build: compile src/ → lib/ with the dsh checkout's tsc.
# Requires DSH_CHECKOUT pointing at a dsh source checkout (auto-probe below).
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

# DSH_CHECKOUT 探测：环境变量 → 常见路径（home 下 dsh-harness / Git checkout）
CHECKOUT="${DSH_CHECKOUT:-}"
if [ -z "$CHECKOUT" ]; then
  for candidate in "$HOME/dsh-harness" "$HOME/dsh" "$HOME/.dsh/dsh-harness" "$HOME/Git/github/deepseek-harness" "$HOME/Git/github/dsh"; do
    if [ -d "$candidate/packages" ]; then CHECKOUT="$candidate"; break; fi
  done
fi
if [ -z "$CHECKOUT" ] || [ ! -d "$CHECKOUT/packages" ]; then
  echo "build: cannot locate the dsh checkout (set DSH_CHECKOUT)" >&2
  exit 1
fi

TSC="$CHECKOUT/node_modules/.bin/tsc"
if [ ! -x "$TSC" ] && [ ! -f "$TSC.cmd" ]; then
  echo "build: tsc not found at $TSC" >&2
  exit 1
fi

link_pkg() {
  local target="$2"
  if [ ! -e "$target" ]; then
    echo "build: dependency target missing: $target" >&2
    exit 1
  fi
  node -e "
    const fs = require('fs');
    const path = require('path');
    const link = path.resolve(process.argv[1]);
    const target = path.resolve(process.argv[2]);
    fs.rmSync(link, { recursive: true, force: true });
    fs.mkdirSync(path.dirname(link), { recursive: true });
    fs.symlinkSync(target, link, process.platform === 'win32' ? 'junction' : 'dir');
  " "node_modules/$1" "$target"
}

# 依赖源解析：**npm 全局 dsh 优先**（插件运行时由 dsh 提供这些 peer，构建期用
# 同一份才能让 dsh-tools 对 @deepseek-ai/cordis 的类型扩充正确合并 ——
# checkout 的 vendor/* 是另一个物理副本，TS 按解析路径区分模块，扩充不合并，
# 表现为 ctx.tools 类型不存在）；checkout 仅作兜底。
GLOBAL_DSH="$(npm root -g 2>/dev/null || true)/@deepseek-ai/dsh"
link_dep() {
  local name="$1" src="$2"
  if [ -e "$GLOBAL_DSH/node_modules/$name/lib" ]; then
    link_pkg "$name" "$GLOBAL_DSH/node_modules/$name"
  elif [ -e "$CHECKOUT/$src/lib" ]; then
    echo "build: $name ← checkout $src（npm 全局 dsh 无此包）"
    link_pkg "$name" "$CHECKOUT/$src"
  else
    echo "build: dependency not found: $name (neither global dsh nor checkout $src has lib)" >&2
    exit 1
  fi
}

echo "=== Linking build dependencies (checkout: $CHECKOUT) ==="
mkdir -p node_modules/@deepseek-ai
node -e "const fs=require('fs');fs.rmSync('node_modules/@standard-schema',{recursive:true,force:true})"
link_dep @deepseek-ai/cordis vendor/cordis
link_dep @deepseek-ai/cosmokit vendor/cosmokit
link_dep @deepseek-ai/schemastery vendor/schemastery
link_dep @deepseek-ai/dsh-tools packages/core/tools
link_dep @deepseek-ai/dsh-llm packages/llm/llm
link_dep @deepseek-ai/dsh-system-prompt packages/core/system-prompt
# @types/node（编译类型；checkout 自带）
link_pkg @types/node "$CHECKOUT/node_modules/@types/node"

STD_SCHEMA=$(find "$CHECKOUT/node_modules/.pnpm" -maxdepth 1 -type d -iname '@standard-schema+spec@*' 2>/dev/null | head -1)
if [ -n "$STD_SCHEMA" ]; then
  node -e "
    const fs = require('fs');
    const path = require('path');
    fs.rmSync('node_modules/@standard-schema', { recursive: true, force: true });
    fs.mkdirSync('node_modules/@standard-schema', { recursive: true });
    fs.symlinkSync(path.resolve(process.argv[1]), path.resolve('node_modules/@standard-schema/spec'), process.platform === 'win32' ? 'junction' : 'dir');
  " "$STD_SCHEMA/node_modules/@standard-schema/spec"
fi

echo "=== Compiling src → lib ==="
"$TSC" -p tsconfig.json
echo "=== Build complete ==="
